#[derive(Default)]struct N{c:[Option<Box<N>>;26],end:bool}struct WordDictionary{r:N}impl WordDictionary{fn new()->Self{Self{r:N::default()}}fn add_word(&mut self,s:String){let mut p=&mut self.r;for b in s.bytes(){p=p.c[(b-b'a')as usize].get_or_insert_with(||Box::new(N::default()));}p.end=true;}fn search(&self,s:String)->bool{fn f(p:&N,b:&[u8],i:usize)->bool{if i==b.len(){return p.end}if b[i]==b'.'{for x in &p.c{if let Some(n)=x.as_ref(){if f(n,b,i+1){return true}}}false}else{p.c[(b[i]-b'a')as usize].as_ref().map(|n|f(n,b,i+1)).unwrap_or(false)}}f(&self.r,s.as_bytes(),0)}}
